import '../../styles/pocEditor.css';

const Playground3D = lazy(() => import('./Playground3D'));
// 🎬 Proof of Content's editor (owner 2026-11-06: "yt editors or content farmers would use this"). Video on Mediabunny, images on Fabric.js, its timeline modeled on what OpenCut and CapCut users expect. Your media stays on this device. Only the edit list reaches the server, and the agent learns your style from the edits you keep.
const EMPTY = { aspect: '16:9', sources: [], clips: [], texts: [], music: [] };
