const clock = t => `${Math.floor(t / 60)}:${String(Math.floor(t % 60)).padStart(2, '0')}.${Math.floor((t % 1) * 10)}`;

function useKeys(fn) { const f = useRef(fn); f.current = fn; useEffect(() => { const on = e => { if (/INPUT|TEXTAREA|SELECT/.test(e.target?.tagName || '')) return; f.current(e); }; window.addEventListener('keydown', on); return () => window.removeEventListener('keydown', on); }, []); }

// 📁 Named edit files (owner 2026-11-10: "new starts a file they name to save and just go"): the open file, every saved one (newest first,
// with its clip count), and New: type a name, press Enter, an empty timeline that saves itself as you work.
