  useEffect(() => { if (!playing) return undefined; let last = performance.now(); let raf = 0; const tick = n => { const dt = (n - last) / 1000; last = n; setT(x => { const y = x + dt; if (y >= total) { setPlaying(false); return total; } return y; }); raf = requestAnimationFrame(tick); }; raf = requestAnimationFrame(tick); return () => cancelAnimationFrame(raf); }, [playing, total]);
  const addFiles = useCallback(async files => { setBusy('add'); setErr(''); for (const f of files) { try { const isAudio = f.type.startsWith('audio/'); const info2 = await probe(f); const id = uid('s'); await putMedia(blobKey(id), f); setThumbs(x => ({ ...x, [id]: info2.thumb })); change(cur => ({ ...cur, sources: [...cur.sources, { id, name: f.name, dur: info2.dur, kind: isAudio || !info2.hasVideo ? 'audio' : 'video', audio: info2.hasAudio }], ...(isAudio || !info2.hasVideo ? { music: [...cur.music, { id: uid('m'), src: id, at: 0, in: 0, out: info2.dur, vol: 0.6 }] } : { clips: [...cur.clips, { id: uid('c'), src: id, in: 0, out: info2.dur, speed: 1, fade: 0, mute: false }] }) })); } catch (e) { setErr(`${f.name} could not be read: ${e.message}`); } } setBusy(''); }, [blobKey, change]);
  useEffect(() => { if (incoming) addFiles([incoming]); }, [incoming]);   // eslint-disable-line react-hooks/exhaustive-deps
  const split = () => { if (!hit) return; const cut = hit.src; if (cut - hit.clip.in < 0.05 || hit.clip.out - cut < 0.05) return; change(cur => ({ ...cur, clips: cur.clips.flatMap(c => (c.id === hit.clip.id ? [{ ...c, out: cut }, { ...c, id: uid('c'), in: cut }] : [c])) })); };
  const del = () => { if (!sel) return; change(cur => ({ ...cur, clips: cur.clips.filter(c => c.id !== sel), texts: cur.texts.filter(x => x.id !== sel), music: cur.music.filter(m => m.id !== sel) })); setSel(null); };
  const undo = () => { if (!past.length) return; setFut(f => [p, ...f]); setP(past[past.length - 1]); setPast(x => x.slice(0, -1)); }; const redo = () => { if (!fut.length) return; setPast(x => [...x, p]); setP(fut[0]); setFut(f => f.slice(1)); };
  useKeys(e => { if (e.key === ' ') { e.preventDefault(); setPlaying(x => !x); } else if (e.key === 's' || e.key === 'S') split(); else if (e.key === 'Delete' || e.key === 'Backspace') del(); else if ((e.metaKey || e.ctrlKey) && e.key === 'z') { e.preventDefault(); if (e.shiftKey) redo(); else undo(); } });
  const putClip = (k, v) => change(cur => ({ ...cur, clips: cur.clips.map(c => (c.id === sel ? { ...c, [k]: v } : c)) })); const putText = (k, v) => change(cur => ({ ...cur, texts: cur.texts.map(x => (x.id === sel ? { ...x, [k]: v } : x)) })); const move = d => change(cur => { const i = cur.clips.findIndex(c => c.id === sel); const j = i + d; if (i < 0 || j < 0 || j >= cur.clips.length) return cur; const c = [...cur.clips]; [c[i], c[j]] = [c[j], c[i]]; return { ...cur, clips: c }; });
  const addText = () => { const n = { id: uid('t'), at: t, dur: 3, text: 'YOUR WORDS', y: 0.8, size: 0.08, color: '#ffffff' }; change(cur => ({ ...cur, texts: [...cur.texts, n] })); setSel(n.id); };
  const trim = (e, c, side) => { e.stopPropagation(); e.preventDefault(); const x0 = e.clientX; const base = p; const s = base.sources.find(x => x.id === c.src); const move2 = ev => { const dt = ((ev.clientX - x0) / zoom) * (c.speed || 1); setP(cur => ({ ...cur, clips: cur.clips.map(k => (k.id !== c.id ? k : side === 'in' ? { ...k, in: Math.max(0, Math.min(c.out - 0.1, c.in + dt)) } : { ...k, out: Math.min(s?.dur || c.out, Math.max(c.in + 0.1, c.out + dt)) })) })); }; const up = () => { window.removeEventListener('pointermove', move2); window.removeEventListener('pointerup', up); setPast(x => [...x.slice(-49), base]); setFut([]); }; window.addEventListener('pointermove', move2); window.addEventListener('pointerup', up); };
