  const exportIt = async () => { setBusy('render'); setPct(0); setErr(''); setSaid(''); try { const started = performance.now(); const blob = await render(p, blobOf, setPct); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `${(name.trim() || 'edit').replace(/[^\w-]+/g, '-')}.mp4`; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 5000); window.__lastRender = { bytes: blob.size, ms: performance.now() - started }; setSaid(`Saved your MP4, ${(blob.size / 1048576).toFixed(1)} MB, made on this device.`); } catch (x) { setErr(x.message); } setBusy(''); };
