  const selClip = p.clips.find(c => c.id === sel); const selText = p.texts.find(x => x.id === sel); const selMusic = p.music.find(m => m.id === sel); const live = p.texts.filter(x => t >= x.at && t < x.at + x.dur); const [W, H] = SIZES[p.aspect]; let run = 0;
